// @grant        GM.xmlHttpRequest
// @grant        GM_xmlhttpRequest
// @grant        GM.getValue
// @grant        GM.setValue
// @connect      raw.githubusercontent.com
// @connect      huggingface.co
// @connect      hf.co
// @connect      xethub.hf.co
// @connect      cdn-lfs.huggingface.co
// @connect      cas-bridge.xethub.hf.co
// ==/UserScript==
